module.exports = "<div class=\"main-container\">\r\n  <div class=\"tools-container\">\r\n    <h2>Magnus Guarantee Certificate</h2>\r\n    <div class=\"left-auto cert-topbar\">\r\n      <span class=\"status inline\" *ngIf=\"status\" [ngClass]=\"statusType\">{{ status }}</span>\r\n      <button class=\"btn-dl top\" (click)=\"generate()\" [disabled]=\"busy\">\r\n        📄 {{ busy ? 'Ban raha hai...' : 'Download PDF' }}\r\n      </button>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"container container-scroll cert-wrap\">\r\n\r\n  <!-- Certificate / Dealer / Customer details (single card) -->\r\n  <div class=\"card\">\r\n    <h2>📝 Certificate Details</h2>\r\n    <div class=\"note\">💡 Har customer ke liye blank Magnus certificate PDF upload karo.</div>\r\n\r\n    <div class=\"sub\">Template</div>\r\n    <div class=\"row\">\r\n      <div class=\"fg\"><label>Certificate PDF Upload</label><input type=\"file\" accept=\".pdf\" (change)=\"onFile($event)\"></div>\r\n      <div class=\"fg\"><label>Certificate Number</label><input [(ngModel)]=\"certNo\"></div>\r\n    </div>\r\n\r\n    <div class=\"sub\">Dealer</div>\r\n    <div class=\"row\">\r\n      <div class=\"fg\"><label>Branch Code</label><input [(ngModel)]=\"branch\"></div>\r\n      <div class=\"fg\"><label>Channel Partner Name</label><input [(ngModel)]=\"partnerName\"></div>\r\n      <div class=\"fg\"><label>Cash Memo / Invoice No.</label><input [(ngModel)]=\"invoiceNo\"></div>\r\n    </div>\r\n\r\n    <div class=\"sub\">Customer</div>\r\n    <div class=\"row\">\r\n      <div class=\"fg\"><label>Customer Name</label><input [(ngModel)]=\"customerName\"></div>\r\n      <div class=\"fg\"><label>Address Line 1</label><input [(ngModel)]=\"addr1\"></div>\r\n      <div class=\"fg\"><label>Address Line 2 (City)</label><input [(ngModel)]=\"addr2\"></div>\r\n    </div>\r\n    <div class=\"row\">\r\n      <div class=\"fg\"><label>Phone Number</label><input [(ngModel)]=\"phone\" placeholder=\"Optional\"></div>\r\n      <div class=\"fg\"><label>Email ID</label><input [(ngModel)]=\"email\" placeholder=\"Optional\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Products -->\r\n  <div class=\"card\">\r\n    <h2>📦 Products</h2>\r\n\r\n    <!-- Add panel: 3 search dropdowns (Product / Thickness / Size) + Qty -->\r\n    <div class=\"add-panel\">\r\n      <div class=\"ap-field ap-product\">\r\n        <label>Product</label>\r\n        <input type=\"text\" [(ngModel)]=\"newRow.name\"\r\n               (focus)=\"openDrop('name')\" (blur)=\"closeDropSoon()\" (keyup.enter)=\"addProduct()\"\r\n               placeholder=\"Select karo ya khud type karo...\">\r\n        <ul class=\"picker-list\" *ngIf=\"openField === 'name' && optionsFor('name').length\">\r\n          <li *ngFor=\"let n of optionsFor('name')\" (mousedown)=\"pick('name', n)\">{{ n }}</li>\r\n        </ul>\r\n      </div>\r\n\r\n      <div class=\"ap-field\">\r\n        <label>Thickness (mm)</label>\r\n        <input type=\"text\" [(ngModel)]=\"newRow.thickness\"\r\n               (focus)=\"openDrop('thickness')\" (blur)=\"closeDropSoon()\" (keyup.enter)=\"addProduct()\"\r\n               placeholder=\"Select ya type\">\r\n        <ul class=\"picker-list\" *ngIf=\"openField === 'thickness' && optionsFor('thickness').length\">\r\n          <li *ngFor=\"let t of optionsFor('thickness')\" (mousedown)=\"pick('thickness', t)\">{{ t }}</li>\r\n        </ul>\r\n      </div>\r\n\r\n      <div class=\"ap-field\">\r\n        <label>Size (ft)</label>\r\n        <input type=\"text\" [(ngModel)]=\"newRow.size\"\r\n               (focus)=\"openDrop('size')\" (blur)=\"closeDropSoon()\" (keyup.enter)=\"addProduct()\"\r\n               placeholder=\"Select ya type\">\r\n        <ul class=\"picker-list\" *ngIf=\"openField === 'size' && optionsFor('size').length\">\r\n          <li *ngFor=\"let s of optionsFor('size')\" (mousedown)=\"pick('size', s)\">{{ s }}</li>\r\n        </ul>\r\n      </div>\r\n\r\n      <div class=\"ap-field ap-qty\">\r\n        <label>Qty (nos)</label>\r\n        <input type=\"text\" [(ngModel)]=\"newRow.qty\" (keyup.enter)=\"addProduct()\" placeholder=\"nos\">\r\n      </div>\r\n\r\n      <button class=\"btn-add ap-btn\" (click)=\"addProduct()\">+ Add</button>\r\n    </div>\r\n    <div class=\"hint\">💡 List me na ho to teeno field me khud type karo aur <b>+ Add</b> (ya Enter) dabao.</div>\r\n\r\n    <!-- Added products table (wide, editable) -->\r\n    <table class=\"prod-table\">\r\n      <thead>\r\n        <tr>\r\n          <th class=\"c-sno\">#</th>\r\n          <th class=\"c-prod\">Product ID</th>\r\n          <th class=\"c-thk\">Thickness (mm)</th>\r\n          <th class=\"c-size\">Size (ft)</th>\r\n          <th class=\"c-qty\">Qty (nos)</th>\r\n          <th class=\"c-act\"></th>\r\n        </tr>\r\n      </thead>\r\n      <tbody>\r\n        <tr *ngIf=\"!products.length\">\r\n          <td colspan=\"6\" class=\"empty\">Abhi koi product add nahi hua — upar se search karke Add karo.</td>\r\n        </tr>\r\n        <tr *ngFor=\"let p of products; let i = index\">\r\n          <td>{{ i + 1 }}</td>\r\n          <td><input type=\"text\" [(ngModel)]=\"p.name\"></td>\r\n          <td><input type=\"text\" [(ngModel)]=\"p.thickness\"></td>\r\n          <td><input type=\"text\" [(ngModel)]=\"p.size\"></td>\r\n          <td><input type=\"text\" [(ngModel)]=\"p.qty\"></td>\r\n          <td><button class=\"btn-del\" (click)=\"delRow(i)\">✕</button></td>\r\n        </tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n\r\n  </div>\r\n</div>\r\n"

