module.exports = "<div class=\"main-container\">\r\n  <div class=\"tools-container\">\r\n    <h2>Daily Field Report</h2>\r\n    <div class=\"left-auto df ac flex-gap-10\">\r\n      <div class=\"date-picker-wrap\">\r\n        <i class=\"material-icons date-icon\">calendar_today</i>\r\n        <input type=\"date\" class=\"date-input\" [(ngModel)]=\"filter.date\" (change)=\"getReport()\">\r\n      </div>\r\n      <button class=\"btn-search\" (click)=\"getReport()\" [disabled]=\"loader\">\r\n        <i class=\"material-icons\">search</i> Search\r\n      </button>\r\n      <button class=\"btn-icon\" matTooltip=\"Refresh\" (click)=\"refresh()\">\r\n        <i class=\"material-icons\">refresh</i>\r\n      </button>\r\n      <button class=\"btn-bulk\" routerLink=\"/report-list/bulk-daily-report\" matTooltip=\"Download reports for multiple users\">\r\n        <i class=\"material-icons\">people</i> Bulk Daily Report\r\n      </button>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Template Bar -->\r\n  <div class=\"tmpl-bar\">\r\n    <span class=\"tmpl-bar-label\"><i class=\"material-icons\">bookmark</i> Templates:</span>\r\n    <div class=\"tmpl-bar-chips\" *ngIf=\"!loadingTemplates\">\r\n      <div\r\n        class=\"tmpl-bar-chip\"\r\n        *ngFor=\"let tmpl of templates\"\r\n        [class.tmpl-bar-chip--active]=\"activeTemplateId === tmpl.id\"\r\n        (click)=\"applyTemplate(tmpl)\"\r\n        matTooltip=\"{{tmpl.user_ids?.length}} user(s)\">\r\n        <i class=\"material-icons\">people</i>\r\n        {{tmpl.template_name}}\r\n        <span class=\"tmpl-bar-count\">{{tmpl.user_ids?.length}}</span>\r\n        <i class=\"material-icons tmpl-edit-icon\" (click)=\"$event.stopPropagation(); openTemplateEditor(tmpl)\" matTooltip=\"Edit template\">edit</i>\r\n      </div>\r\n      <button class=\"tmpl-bar-clear\" *ngIf=\"activeTemplateId\" (click)=\"clearTemplate()\" matTooltip=\"Clear template filter\">\r\n        <i class=\"material-icons\">close</i> Clear\r\n      </button>\r\n      <button class=\"tmpl-bar-new\" (click)=\"openTemplateEditor()\" matTooltip=\"Create new template\">\r\n        <i class=\"material-icons\">add</i> New\r\n      </button>\r\n    </div>\r\n    <div class=\"tmpl-bar-skeleton\" *ngIf=\"loadingTemplates\">\r\n      <div class=\"sk-tmpl\" *ngFor=\"let i of [].constructor(3)\">&nbsp;</div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"container container-scroll\">\r\n\r\n    <!-- Report Table -->\r\n    <div class=\"report-table-section\" *ngIf=\"reportData.length > 0 && !loader\">\r\n      <div class=\"table-section-title\">\r\n        <div class=\"table-title-left\">\r\n          <h3><i class=\"material-icons table-title-icon\">assignment</i> Daily Field Report</h3>\r\n          <span class=\"section-subtitle\">{{formatDateFull(filter.date)}}</span>\r\n        </div>\r\n        <button class=\"btn-download\" (click)=\"downloadExcel()\" [disabled]=\"downloading\">\r\n          <i class=\"material-icons\">{{downloading ? 'hourglass_top' : 'file_download'}}</i>\r\n          {{downloading ? 'Downloading...' : 'Download Excel'}}\r\n        </button>\r\n      </div>\r\n\r\n      <div class=\"cs-table horizontal-scroll\">\r\n        <table class=\"field-report-table\">\r\n          <thead>\r\n            <tr>\r\n              <th class=\"w50 text-center sticky-col\">S.No</th>\r\n              <th class=\"w120\">Desig</th>\r\n              <th class=\"w180 sticky-col-2\">Name</th>\r\n              <th class=\"w100\">Code</th>\r\n              <th class=\"w120\">Based Loc</th>\r\n              <th class=\"w80\">POA</th>\r\n              <th class=\"w80 text-center\">Visit Plan</th>\r\n              <th class=\"w50 text-center\">Att</th>\r\n              <th class=\"w50 text-center\">Att</th>\r\n              <th class=\"w200\">START LOC</th>\r\n              <th class=\"w90 text-center\">SFH TIME</th>\r\n              <th class=\"w80 text-center\">SFH-C1 km</th>\r\n              <th class=\"w100 text-center\">FST CHECK-IN</th>\r\n              <th class=\"w60 text-center\">11AM</th>\r\n              <th class=\"w60 text-center\">12PM</th>\r\n              <th class=\"w60 text-center\">2PM</th>\r\n              <th class=\"w60 text-center\">4PM</th>\r\n              <th class=\"w60 text-center\">6PM</th>\r\n              <th class=\"w60 text-center\">TOTAL</th>\r\n              <th class=\"w100 text-center\">L CHECKOUT</th>\r\n              <th class=\"w80 text-center\">LC-STH KM</th>\r\n              <th class=\"w90 text-center\">STH</th>\r\n              <th class=\"w100 text-center\">GOOGLE KM</th>\r\n              <th class=\"w100 text-center\">ACTUAL KM</th>\r\n              <th class=\"w60 text-center\">Lead</th>\r\n              <th class=\"w80 text-center\">Secondary Qty</th>\r\n            </tr>\r\n            <tr class=\"filter-row\">\r\n              <th class=\"w50\"></th>\r\n              <th class=\"w120\"></th>\r\n              <th class=\"w180\">\r\n                <div class=\"col-filter\">\r\n                  <i class=\"material-icons filter-icon\">search</i>\r\n                  <input type=\"text\" class=\"col-filter-input\" placeholder=\"Name...\" [(ngModel)]=\"searchName\"\r\n                    (keyup.enter)=\"getReport()\">\r\n                </div>\r\n              </th>\r\n              <th class=\"w100\">\r\n                <div class=\"col-filter\">\r\n                  <i class=\"material-icons filter-icon\">search</i>\r\n                  <input type=\"text\" class=\"col-filter-input\" placeholder=\"Code...\" [(ngModel)]=\"searchCode\"\r\n                    (keyup.enter)=\"getReport()\">\r\n                </div>\r\n              </th>\r\n              <th class=\"w120\"></th>\r\n              <th class=\"w80\"></th>\r\n              <th class=\"w80\"></th>\r\n              <th class=\"w50\"></th>\r\n              <th class=\"w50\"></th>\r\n              <th class=\"w200\"></th>\r\n              <th class=\"w90\"></th>\r\n              <th class=\"w80\"></th>\r\n              <th class=\"w100\"></th>\r\n              <th class=\"w60\"></th>\r\n              <th class=\"w60\"></th>\r\n              <th class=\"w60\"></th>\r\n              <th class=\"w60\"></th>\r\n              <th class=\"w60\"></th>\r\n              <th class=\"w60\"></th>\r\n              <th class=\"w100\"></th>\r\n              <th class=\"w80\"></th>\r\n              <th class=\"w90\"></th>\r\n              <th class=\"w100\"></th>\r\n              <th class=\"w100\"></th>\r\n              <th class=\"w60\"></th>\r\n              <th class=\"w80\"></th>\r\n            </tr>\r\n          </thead>\r\n          <tbody>\r\n            <ng-container *ngIf=\"!loader\">\r\n              <tr *ngFor=\"let row of filteredData; let i = index\">\r\n                <td class=\"w50 text-center\">{{i + 1}}</td>\r\n                <td class=\"w120 one-line\" matTooltip=\"{{row.designation_name}}\">{{row.designation_name || '--'}}</td>\r\n                <td class=\"w180\">\r\n                  <span class=\"user-name-text\">{{row.name | titlecase}}</span>\r\n                </td>\r\n                <td class=\"w100\">{{row.employee_id || '--'}}</td>\r\n                <td class=\"w120 one-line\" matTooltip=\"{{row.based_loc}}\">{{row.based_loc || '--'}}</td>\r\n                <td class=\"w80\">{{row.poa || '--'}}</td>\r\n                <td class=\"w80 text-center\"><strong>{{row.visit_plan_count || 0}}</strong></td>\r\n                <td class=\"w50 text-center\"></td>\r\n                <td class=\"w50 text-center\"></td>\r\n                <td class=\"w200 one-line\" matTooltip=\"{{row.start_loc}}\">{{row.start_loc || '--'}}</td>\r\n                <td class=\"w90 text-center\">{{formatTime(row.sfh_time)}}</td>\r\n                <td class=\"w80 text-center\">\r\n                  <span [ngClass]=\"{'km-value': row.sfh_c1_km != '--'}\">{{row.sfh_c1_km}}</span>\r\n                </td>\r\n                <td class=\"w100 text-center\">{{formatTime(row.fst_checkin)}}</td>\r\n                <td class=\"w60 text-center\">\r\n                  <span class=\"count-badge\" *ngIf=\"row.count_11am > 0\">{{row.count_11am}}</span>\r\n                  <span *ngIf=\"row.count_11am == 0\">0</span>\r\n                </td>\r\n                <td class=\"w60 text-center\">\r\n                  <span class=\"count-badge\" *ngIf=\"row.count_12pm > 0\">{{row.count_12pm}}</span>\r\n                  <span *ngIf=\"row.count_12pm == 0\">0</span>\r\n                </td>\r\n                <td class=\"w60 text-center\">\r\n                  <span class=\"count-badge\" *ngIf=\"row.count_2pm > 0\">{{row.count_2pm}}</span>\r\n                  <span *ngIf=\"row.count_2pm == 0\">0</span>\r\n                </td>\r\n                <td class=\"w60 text-center\">\r\n                  <span class=\"count-badge\" *ngIf=\"row.count_4pm > 0\">{{row.count_4pm}}</span>\r\n                  <span *ngIf=\"row.count_4pm == 0\">0</span>\r\n                </td>\r\n                <td class=\"w60 text-center\">\r\n                  <span class=\"count-badge\" *ngIf=\"row.count_6pm > 0\">{{row.count_6pm}}</span>\r\n                  <span *ngIf=\"row.count_6pm == 0\">0</span>\r\n                </td>\r\n                <td class=\"w60 text-center\">\r\n                  <strong>{{row.total_checkins}}</strong>\r\n                </td>\r\n                <td class=\"w100 text-center\">{{formatTime(row.last_checkout)}}</td>\r\n                <td class=\"w80 text-center\">\r\n                  <span [ngClass]=\"{'km-value': row.lc_sth_km != '--'}\">{{row.lc_sth_km}}</span>\r\n                </td>\r\n                <td class=\"w90 text-center\">{{formatTime(row.sth)}}</td>\r\n                <td class=\"w100 text-center\">{{row.shortest_distance_km}}</td>\r\n                <td class=\"w100 text-center\">{{row.actual_km}}</td>\r\n                <td class=\"w60 text-center\">\r\n                  <span class=\"lead-badge\" *ngIf=\"row.lead_count > 0\">{{row.lead_count}}</span>\r\n                  <span *ngIf=\"row.lead_count == 0\">0</span>\r\n                </td>\r\n                <td class=\"w80 text-center\">\r\n                  <span class=\"sec-badge\" *ngIf=\"row.secondary_qty > 0\">{{row.secondary_qty}}</span>\r\n                  <span *ngIf=\"row.secondary_qty == 0\">0</span>\r\n                </td>\r\n              </tr>\r\n            </ng-container>\r\n          </tbody>\r\n        </table>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Skeleton Loader -->\r\n    <div *ngIf=\"loader\" class=\"skeleton-section\">\r\n      <div class=\"skeleton-table-wrap\">\r\n        <div class=\"skeleton-loader sk-table-row\" *ngFor=\"let i of [].constructor(8)\">&nbsp;</div>\r\n      </div>\r\n    </div>\r\n\r\n    <div *ngIf=\"datanotfound && !loader\">\r\n      <app-not-result-found></app-not-result-found>\r\n    </div>\r\n\r\n  </div>\r\n</div>"

