            styles: ["\n    .sbd-container { width: 520px; font-family: inherit; }\n\n    .sbd-header {\n      display: flex; align-items: center; justify-content: space-between;\n      padding: 16px 20px; border-bottom: 1px solid #f1f5f9;\n      background: linear-gradient(135deg,#1e293b,#334155);\n    }\n    .sbd-header-left { display: flex; align-items: center; gap: 12px; }\n    .sbd-header-left i { font-size: 26px; color: #10B981; background: rgba(16,185,129,0.15); border-radius: 8px; padding: 6px; }\n    .sbd-header-left h3 { margin: 0 0 2px; font-size: 15px; font-weight: 700; color: #F1F5F9; }\n    .sbd-header-left p  { margin: 0; font-size: 12px; color: #94a3b8; }\n    .sbd-header button { color: #94a3b8; }\n\n    .sbd-loader { display: flex; align-items: center; justify-content: center; gap: 10px; padding: 40px; color: #64748b; }\n    .sbd-spinner { width: 22px; height: 22px; border: 3px solid #e2e8f0; border-top-color: #10B981; border-radius: 50%; animation: spin 0.7s linear infinite; }\n    @keyframes spin { to { transform: rotate(360deg); } }\n\n    .sbd-empty { text-align: center; padding: 40px 20px; color: #94a3b8; }\n    .sbd-empty i { font-size: 40px; display: block; margin-bottom: 8px; }\n    .sbd-empty p { margin: 0; font-size: 14px; }\n\n    .sbd-body { padding: 16px 20px; }\n    .sbd-total-bar {\n      display: flex; justify-content: space-between; align-items: center;\n      background: #ECFDF5; border: 1px solid #A7F3D0; border-radius: 8px;\n      padding: 10px 16px; margin-bottom: 14px; font-size: 13px; color: #065f46;\n      strong { font-size: 18px; font-weight: 700; }\n    }\n\n    .sbd-table { width: 100%; border-collapse: collapse; font-size: 13px; }\n    .sbd-table th, .sbd-table td { padding: 10px 12px; border-bottom: 1px solid #f1f5f9; }\n    .sbd-table th { font-size: 11px; font-weight: 600; color: #475569; background: #f8fafc; }\n    .sbd-table tr:hover td { background: #f0fdf8; }\n    .text-center { text-align: center; }\n    .text-muted { color: #94a3b8; }\n\n    .pct-badge { background: #D1FAE5; color: #065f46; border-radius: 20px; padding: 2px 8px; font-size: 11px; font-weight: 700; }\n\n    .share-bar-wrap { background: #e2e8f0; border-radius: 4px; height: 8px; overflow: hidden; }\n    .share-bar { background: linear-gradient(90deg, #10B981, #059669); height: 100%; border-radius: 4px; transition: width 0.4s ease; min-width: 2px; }\n  "]
