module.exports = "<div class=\"main-container\">\r\n  <div class=\"tools-container\">\r\n    <h2>Employee Attendance</h2>\r\n  </div>\r\n\r\n  <div class=\"container container-scroll\">\r\n\r\n    <!-- Filter Form -->\r\n    <div class=\"att-form-card\">\r\n      <div class=\"form-row\">\r\n        <div class=\"form-field\">\r\n          <label>Employee ID</label>\r\n          <input type=\"text\" [(ngModel)]=\"filter.empid\" placeholder=\"e.g. S1684\">\r\n        </div>\r\n        <div class=\"form-field\">\r\n          <label>Company ID</label>\r\n          <input type=\"text\" [(ngModel)]=\"filter.company_id\" placeholder=\"e.g. 426\">\r\n        </div>\r\n        <div class=\"form-field\">\r\n          <label>Month</label>\r\n          <select [(ngModel)]=\"filter.month\">\r\n            <option *ngFor=\"let m of months\" [ngValue]=\"m.v\">{{m.n}}</option>\r\n          </select>\r\n        </div>\r\n        <div class=\"form-field\">\r\n          <label>Year</label>\r\n          <select [(ngModel)]=\"filter.year\">\r\n            <option *ngFor=\"let y of years\" [ngValue]=\"y\">{{y}}</option>\r\n          </select>\r\n        </div>\r\n        <div class=\"form-field form-action\">\r\n          <button class=\"btn-search\" (click)=\"generate()\" [disabled]=\"loader\">\r\n            <i class=\"material-icons\">search</i> Fetch\r\n          </button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Loader -->\r\n    <div class=\"att-loader\" *ngIf=\"loader\">\r\n      <i class=\"material-icons spin\">autorenew</i>\r\n      <span>Fetching attendance...</span>\r\n    </div>\r\n\r\n    <!-- Empty state -->\r\n    <div class=\"att-empty\" *ngIf=\"!loader && !hasData\">\r\n      <i class=\"material-icons\">event_available</i>\r\n      <p>Enter the details above and click <b>Fetch</b> to view the attendance dashboard.</p>\r\n    </div>\r\n\r\n    <!-- Dashboard -->\r\n    <div class=\"att-dash\" *ngIf=\"!loader && hasData\">\r\n\r\n      <div class=\"dash-head\">\r\n        <div>\r\n          <h3>{{ filter.empid }}</h3>\r\n          <span>{{ periodLabel }}</span>\r\n        </div>\r\n        <div class=\"att-badge\" [class.good]=\"summary.attendancePct >= 90\"\r\n             [class.warn]=\"summary.attendancePct >= 60 && summary.attendancePct < 90\"\r\n             [class.bad]=\"summary.attendancePct < 60\">\r\n          <span>Attendance</span>\r\n          <b>{{ summary.attendancePct }}%</b>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- KPI tiles -->\r\n      <div class=\"kpi-grid\">\r\n        <div class=\"kpi\"><span class=\"kpi-num st-present-t\">{{ summary.present }}</span><span class=\"kpi-lbl\">Present</span></div>\r\n        <div class=\"kpi\"><span class=\"kpi-num st-absent-t\">{{ summary.absent }}</span><span class=\"kpi-lbl\">Absent</span></div>\r\n        <div class=\"kpi\"><span class=\"kpi-num st-rest-t\">{{ summary.rest }}</span><span class=\"kpi-lbl\">Rest / Off</span></div>\r\n        <div class=\"kpi\"><span class=\"kpi-num st-leave-t\">{{ summary.leave }}</span><span class=\"kpi-lbl\">Leave</span></div>\r\n        <div class=\"kpi\"><span class=\"kpi-num\">{{ summary.totalHrs }}</span><span class=\"kpi-lbl\">Total Hours</span></div>\r\n        <div class=\"kpi\"><span class=\"kpi-num\">{{ summary.avgHrs }}</span><span class=\"kpi-lbl\">Avg Hrs/Day</span></div>\r\n      </div>\r\n\r\n      <!-- Distribution bar -->\r\n      <div class=\"dist-card\" *ngIf=\"distribution.length\">\r\n        <div class=\"card-title\">Status Distribution</div>\r\n        <div class=\"dist-bar\">\r\n          <div class=\"seg\" *ngFor=\"let s of distribution\" [ngClass]=\"s.cls\"\r\n               [style.width.%]=\"s.pct\" [attr.title]=\"s.label + ': ' + s.value\"></div>\r\n        </div>\r\n        <div class=\"legend\">\r\n          <span class=\"lg\" *ngFor=\"let s of legend\">\r\n            <i class=\"dot\" [ngClass]=\"s.cls\"></i>{{ s.label }} <b>{{ s.value }}</b>\r\n          </span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Calendar heatmap -->\r\n      <div class=\"cal-card\">\r\n        <div class=\"card-title\">Monthly Calendar</div>\r\n        <div class=\"cal-grid cal-head\">\r\n          <div class=\"cal-dow\" *ngFor=\"let w of weekDayNames\">{{ w }}</div>\r\n        </div>\r\n        <div class=\"cal-grid\" *ngFor=\"let week of weeks\">\r\n          <div class=\"cal-cell\" *ngFor=\"let day of week\"\r\n               [ngClass]=\"day ? day.cls : 'empty'\"\r\n               [attr.title]=\"day ? (day.statusDet + (day.fromTime ? ' | ' + day.fromTime + ' - ' + day.toTime : '')) : ''\">\r\n            <ng-container *ngIf=\"day\">\r\n              <span class=\"c-date\">{{ day.dayNum }}</span>\r\n              <span class=\"c-status\">{{ day.status }}</span>\r\n            </ng-container>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Day-wise table -->\r\n      <div class=\"log-card\">\r\n        <div class=\"card-title\">Day-wise Log</div>\r\n        <div class=\"log-row log-head\">\r\n          <span class=\"c-day\">Date</span>\r\n          <span class=\"c-st\">Status</span>\r\n          <span class=\"c-in\">In</span>\r\n          <span class=\"c-out\">Out</span>\r\n          <span class=\"c-hr\">Hrs</span>\r\n        </div>\r\n        <div class=\"log-row\" *ngFor=\"let day of days\">\r\n          <span class=\"c-day\">{{ day.dayNum }} <small>{{ day.dayName }}</small></span>\r\n          <span class=\"c-st\"><i class=\"dot\" [ngClass]=\"day.cls\"></i>{{ day.label }}</span>\r\n          <span class=\"c-in\">{{ day.fromTime || '—' }}</span>\r\n          <span class=\"c-out\">{{ day.toTime || '—' }}</span>\r\n          <span class=\"c-hr\">{{ day.totalHrs || '—' }}</span>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n\r\n  </div>\r\n</div>\r\n"

