module.exports = "<div class=\"main-container\">\r\n  <div class=\"tools-container\">\r\n    <h2>Employee Pay Slip</h2>\r\n  </div>\r\n\r\n  <div class=\"container container-scroll\">\r\n\r\n    <!-- Filter Form -->\r\n    <div class=\"payslip-form-card\">\r\n      <div class=\"form-row\">\r\n        <div class=\"form-field\">\r\n          <label>Employee ID</label>\r\n          <input type=\"text\" [(ngModel)]=\"filter.empid\" placeholder=\"e.g. S1684\">\r\n        </div>\r\n        <div class=\"form-field\">\r\n          <label>Company ID</label>\r\n          <input type=\"text\" [(ngModel)]=\"filter.company_id\" placeholder=\"e.g. 426\">\r\n        </div>\r\n        <div class=\"form-field\">\r\n          <label>Month</label>\r\n          <select [(ngModel)]=\"filter.month\">\r\n            <option *ngFor=\"let m of months\" [ngValue]=\"m.v\">{{m.n}}</option>\r\n          </select>\r\n        </div>\r\n        <div class=\"form-field\">\r\n          <label>Year</label>\r\n          <select [(ngModel)]=\"filter.year\">\r\n            <option *ngFor=\"let y of years\" [ngValue]=\"y\">{{y}}</option>\r\n          </select>\r\n        </div>\r\n        <div class=\"form-field form-action\">\r\n          <button class=\"btn-search\" (click)=\"generate()\" [disabled]=\"loader\">\r\n            <i class=\"material-icons\">picture_as_pdf</i> Generate\r\n          </button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Loader -->\r\n    <div class=\"payslip-loader\" *ngIf=\"loader\">\r\n      <i class=\"material-icons spin\">autorenew</i>\r\n      <span>Generating pay slip...</span>\r\n    </div>\r\n\r\n    <!-- Empty state -->\r\n    <div class=\"payslip-empty\" *ngIf=\"!loader && !hasPdf\">\r\n      <i class=\"material-icons\">description</i>\r\n      <p>Enter the details above and click <b>Generate</b> to view the pay slip.</p>\r\n    </div>\r\n\r\n    <!-- PDF Preview -->\r\n    <div class=\"payslip-preview\" *ngIf=\"!loader && hasPdf\">\r\n      <div class=\"preview-head\">\r\n        <span class=\"file-name\"><i class=\"material-icons\">picture_as_pdf</i> {{fileName}}</span>\r\n        <button class=\"btn-download\" (click)=\"download()\">\r\n          <i class=\"material-icons\">download</i> Download\r\n        </button>\r\n      </div>\r\n      <iframe [src]=\"pdfUrl\" class=\"pdf-frame\" frameborder=\"0\"></iframe>\r\n    </div>\r\n\r\n    <!-- Salary breakdown -->\r\n    <div class=\"salary-view\" *ngIf=\"!loader && salaryData\">\r\n\r\n      <div class=\"salary-top\">\r\n        <div class=\"top-left\">\r\n          <h3 class=\"company\">{{ companyName }}</h3>\r\n          <p class=\"period\"><i class=\"material-icons\">event</i> {{ salaryHeading }}</p>\r\n          <p class=\"emp\" *ngIf=\"empName\">\r\n            <i class=\"material-icons\">person</i> {{ empName }}\r\n            <span *ngIf=\"designation\"> &middot; {{ designation }}</span>\r\n          </p>\r\n        </div>\r\n        <div class=\"net-box\" *ngIf=\"netPayable !== null\">\r\n          <span>Net Payable</span>\r\n          <b>&#8377; {{ netPayable | number }}</b>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"salary-grid\">\r\n        <div class=\"salary-card\" *ngFor=\"let sec of sections\">\r\n          <div class=\"sec-title\">{{ sec.title }}</div>\r\n          <div class=\"sec-row\" *ngFor=\"let r of sec.rows\" [class.is-total]=\"r.isTotal\">\r\n            <span class=\"r-title\">{{ r.title }}</span>\r\n            <span class=\"r-value\">{{ r.value }}</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"bank-card\" *ngIf=\"bank\">\r\n        <i class=\"material-icons\">account_balance</i>\r\n        <div class=\"bank-info\">\r\n          <span>{{ bank.name }}</span>\r\n          <small *ngIf=\"bank.acc_no\">A/C: {{ bank.acc_no }}</small>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n\r\n  </div>\r\n</div>\r\n"

