    MasterReportComponent.prototype.onKmChange = function (row, index) {
        if (row.start_km != null && row.close_km != null) {
            row.total_km = row.close_km - row.start_km;
            if (row.total_km < 0)
                row.total_km = 0;
        }
        this.modifiedRows.add(index);
    };
    MasterReportComponent.prototype.saveBulkUpdate = function () {
        var _this = this;
        if (this.modifiedRows.size === 0) {
            this.toast.errorToastr('No changes to save');
            return;
        }
        var expenses = [];
        this.modifiedRows.forEach(function (index) {
            var row = _this.ExpenseDetail[index];
            if (row && row.expenseId) {
                expenses.push({
                    expenseId: row.expenseId,
                    userId: _this.id,
                    start_km: row.start_km,
                    close_km: row.close_km,
                    claimDate: row.date
                });
            }
        });
        if (expenses.length === 0) {
            this.toast.errorToastr('No valid expenses to update');
            return;
        }
        this.bulkSaving = true;
        this.service.post_rqst({ expenses: expenses }, "Attendance/bulk_update_ta_expense")
            .subscribe(function (result) {
            if (result['statusCode'] == 200) {
                _this.toast.successToastr(result['statusMsg']);
                _this.isEditMode = false;
                _this.modifiedRows.clear();
                _this.getExpenseReport();
            }
            else {
                _this.toast.errorToastr(result['statusMsg']);
            }
            _this.bulkSaving = false;
        }, function (error) {
            _this.bulkSaving = false;
            _this.toast.errorToastr('Failed to update expenses');
        });
    };
    // Route to the attendance detail page for the clicked expense row's date
    MasterReportComponent.prototype.goToAttendanceDetail = function (row) {
        if (!row || !row.attendance_id) {
            this.toast.errorToastr('No attendance found for this date');
            return;
        }
        // Keep this day open on return; the typed remark is already saved as a draft
        // via onRemarkChange(), so it will be restored after the report re-loads.
        this.service.expenseOpenDate = row.claimDate || this.expandedDate;
        this.routes.navigate(['/attendance/attendance-detail/' + row.attendance_id + '/' + this.id + '/' + row.claimDate]);
    };
