    // Build the month grid (weeks of 7 day-slots) from filter.year / filter.month
    MasterReportComponent.prototype.buildCalendar = function () {
        this.calendarWeeks = [];
        if (!this.filter || !this.filter.year || !this.filter.month) {
            return;
        }
        var monthStart = moment__WEBPACK_IMPORTED_MODULE_2__(this.filter.year + '-' + this.filter.month + '-01', 'YYYY-M-DD');
        if (!monthStart.isValid()) {
            return;
        }
        var daysInMonth = monthStart.daysInMonth();
        var firstWeekday = monthStart.day(); // 0 = Sunday ... 6 = Saturday
        var week = [];
        // leading blanks before day 1
        for (var i = 0; i < firstWeekday; i++) {
            week.push({ inMonth: false });
        }
        for (var d = 1; d <= daysInMonth; d++) {
            var date = monthStart.clone().date(d).format('YYYY-MM-DD');
            week.push({
                inMonth: true,
                day: d,
                date: date,
                expense: this.expenseByDate[date] || null
            });
            if (week.length === 7) {
                this.calendarWeeks.push(week);
                week = [];
            }
        }
        // trailing blanks to complete the last week
        if (week.length > 0) {
            while (week.length < 7) {
                week.push({ inMonth: false });
            }
            this.calendarWeeks.push(week);
        }
    };
