                // Day is saved server-side now, so drop its draft remark + remembered open day.
                if (expense && expense.id != null) {
                    delete _this.service.expenseRemarkDrafts[expense.id];
                }
                _this.service.expenseOpenDate = '';
                _this.expandedDate = '';
                _this.getMonthExpenseReport();
