module.exports = "<div class=\"main-container\">\r\n  <div class=\"tools-container\">\r\n    <h2>Pending Expense Report</h2>\r\n    <div class=\"left-auto left-auto df ac flex-gap-10\">\r\n      <div class=\"date-picker-wrap\">\r\n        <i class=\"material-icons date-icon\">calendar_today</i>\r\n        <input type=\"date\" class=\"date-input\" [(ngModel)]=\"filter.date_from\">\r\n      </div>\r\n      <span class=\"date-separator\">to</span>\r\n      <div class=\"date-picker-wrap\">\r\n        <i class=\"material-icons date-icon\">calendar_today</i>\r\n        <input type=\"date\" class=\"date-input\" [(ngModel)]=\"filter.date_to\">\r\n      </div>\r\n      <button class=\"btn-search\" (click)=\"getReport()\" [disabled]=\"loader\">\r\n        <i class=\"material-icons\">search</i> Search\r\n      </button>\r\n      <button class=\"btn-icon\" matTooltip=\"Refresh\" (click)=\"refresh()\">\r\n        <i class=\"material-icons\">refresh</i>\r\n      </button>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Template Bar -->\r\n  <div class=\"tmpl-bar\">\r\n    <span class=\"tmpl-bar-label\"><i class=\"material-icons\">bookmark</i> Templates:</span>\r\n    <div class=\"tmpl-bar-chips\" *ngIf=\"!loadingTemplates\">\r\n      <div\r\n        class=\"tmpl-bar-chip\"\r\n        *ngFor=\"let tmpl of templates\"\r\n        [class.tmpl-bar-chip--active]=\"activeTemplateId === tmpl.id\"\r\n        (click)=\"applyTemplate(tmpl)\"\r\n        matTooltip=\"{{tmpl.user_ids?.length}} user(s)\">\r\n        <i class=\"material-icons\">people</i>\r\n        {{tmpl.template_name}}\r\n        <span class=\"tmpl-bar-count\">{{tmpl.user_ids?.length}}</span>\r\n        <i class=\"material-icons tmpl-edit-icon\" (click)=\"$event.stopPropagation(); openTemplateEditor(tmpl)\" matTooltip=\"Edit template\">edit</i>\r\n      </div>\r\n      <button class=\"tmpl-bar-clear\" *ngIf=\"activeTemplateId\" (click)=\"clearTemplate()\" matTooltip=\"Clear template filter\">\r\n        <i class=\"material-icons\">close</i> Clear\r\n      </button>\r\n      <button class=\"tmpl-bar-new\" (click)=\"openTemplateEditor()\" matTooltip=\"Create new template\">\r\n        <i class=\"material-icons\">add</i> New\r\n      </button>\r\n    </div>\r\n    <div class=\"tmpl-bar-skeleton\" *ngIf=\"loadingTemplates\">\r\n      <div class=\"sk-tmpl\" *ngFor=\"let i of [].constructor(3)\">&nbsp;</div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"container container-scroll\">\r\n\r\n    <!-- Summary Stats -->\r\n    <div class=\"dashboard-section\" *ngIf=\"reportData.length > 0 && !loader\">\r\n      <div class=\"section-header\">\r\n        <div class=\"section-header-left\">\r\n          <h3>Overview</h3>\r\n          <span class=\"date-tag\"><i class=\"material-icons\">date_range</i> {{formatDateFull(filter.date_from)}} -\r\n            {{formatDateFull(filter.date_to)}}</span>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"stats-grid\">\r\n        <div class=\"stat-card\">\r\n          <div class=\"stat-top\">\r\n            <div class=\"stat-icon-wrap bg-blue\"><i class=\"material-icons\">people</i></div>\r\n            <span class=\"stat-number clr-blue\">{{reportData.length}}</span>\r\n          </div>\r\n          <div class=\"stat-label\">Sales Users with Pending</div>\r\n          <div class=\"stat-bar bar-blue\"></div>\r\n        </div>\r\n        <div class=\"stat-card\">\r\n          <div class=\"stat-top\">\r\n            <div class=\"stat-icon-wrap bg-red\"><i class=\"material-icons\">warning</i></div>\r\n            <span class=\"stat-number clr-red\">{{totalPending}}</span>\r\n          </div>\r\n          <div class=\"stat-label\">Total Pending Expense Days</div>\r\n          <div class=\"stat-bar bar-red\"></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Report Table -->\r\n    <div class=\"report-table-section\" *ngIf=\"reportData.length > 0 && !loader\">\r\n      <div class=\"table-section-title\">\r\n        <div class=\"table-title-left\">\r\n          <h3><i class=\"material-icons table-title-icon\">receipt_long</i> Pending TA Expense Report</h3>\r\n          <span class=\"section-subtitle\">Sales users jo present the lekin TA expense nahi dali</span>\r\n        </div>\r\n        <button class=\"btn-download\" (click)=\"downloadExcel()\" [disabled]=\"downloading\">\r\n          <i class=\"material-icons\">{{downloading ? 'hourglass_top' : 'file_download'}}</i>\r\n          {{downloading ? 'Downloading...' : 'Download Excel'}}\r\n        </button>\r\n      </div>\r\n      <div class=\"cs-table horizontal-scroll\">\r\n        <div class=\"table-head\">\r\n          <table>\r\n            <tr>\r\n              <th class=\"w60 text-center\">S.No</th>\r\n              <th class=\"w220\">Sales Operation Executive</th>\r\n              <th class=\"w200\">Name of Sales User</th>\r\n              <th class=\"w130\">Employee Code</th>\r\n              <th class=\"pending-dates-header\">Pending Dates</th>\r\n            </tr>\r\n            <tr class=\"filter-row\">\r\n              <th class=\"w60\"></th>\r\n              <th class=\"w220\">\r\n                <div class=\"col-filter\">\r\n                  <i class=\"material-icons filter-icon\">search</i>\r\n                  <input type=\"text\" class=\"col-filter-input\" placeholder=\"Filter SOE...\" [(ngModel)]=\"searchSOE\"\r\n                    (input)=\"filterData()\">\r\n                </div>\r\n              </th>\r\n              <th class=\"w200\">\r\n                <div class=\"col-filter\">\r\n                  <i class=\"material-icons filter-icon\">search</i>\r\n                  <input type=\"text\" class=\"col-filter-input\" placeholder=\"Filter User...\" [(ngModel)]=\"searchUser\"\r\n                    (input)=\"filterData()\">\r\n                </div>\r\n              </th>\r\n              <th class=\"w130\"></th>\r\n              <th class=\"pending-dates-header\"></th>\r\n            </tr>\r\n          </table>\r\n        </div>\r\n        <div class=\"table-content\">\r\n          <table>\r\n            <tr *ngFor=\"let row of filteredData; let i = index\">\r\n              <td class=\"w60 text-center\">{{i + 1}}</td>\r\n              <td class=\"w220 soe-name\">{{row.system_user_names}}</td>\r\n              <td class=\"w200\">\r\n                <div class=\"user-cell\">\r\n                  <div class=\"user-avatar\">{{(row.sales_user_name || 'U').charAt(0).toUpperCase()}}</div>\r\n                  <span class=\"user-name\">{{row.sales_user_name}}</span>\r\n                </div>\r\n              </td>\r\n              <td class=\"w130\">{{row.employee_code ? row.employee_code : '--'}}</td>\r\n              <td class=\"pending-dates-cell\">\r\n                <div class=\"dates-wrap\">\r\n                  <span class=\"pending-date\" style=\"cursor: pointer;\" *ngFor=\"let d of row.pending_dates\"\r\n                    (click)=\"goToAttendanceDetail(d.attendance_id, row.sales_user_id, d.date)\">{{formatDate(d.date)}}</span>\r\n                </div>\r\n              </td>\r\n            </tr>\r\n          </table>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Skeleton Loader -->\r\n    <div *ngIf=\"loader\" class=\"skeleton-section\">\r\n      <div class=\"stats-grid\">\r\n        <div class=\"skeleton-card\" *ngFor=\"let i of [].constructor(2)\">\r\n          <div class=\"skeleton-loader sk-circle\">&nbsp;</div>\r\n          <div class=\"skeleton-loader sk-line\">&nbsp;</div>\r\n          <div class=\"skeleton-loader sk-line-sm\">&nbsp;</div>\r\n        </div>\r\n      </div>\r\n      <div class=\"skeleton-table-wrap\">\r\n        <div class=\"skeleton-loader sk-table-row\" *ngFor=\"let i of [].constructor(5)\">&nbsp;</div>\r\n      </div>\r\n    </div>\r\n\r\n    <div *ngIf=\"datanotfound && !loader\">\r\n      <app-not-result-found></app-not-result-found>\r\n    </div>\r\n\r\n  </div>\r\n</div>"

