module.exports = "<div class=\"main-container\">\r\n\r\n  <div class=\"tools-container\">\r\n    <h2>Performance Summary Report</h2>\r\n  </div>\r\n\r\n  <div class=\"container container-scroll\">\r\n    <div class=\"psr-page\">\r\n\r\n      <!-- Mode Toggle -->\r\n      <div class=\"psr-mode-toggle\">\r\n        <button class=\"psr-mode-btn\" [class.active]=\"mode === 'quarter'\" (click)=\"switchMode('quarter')\">\r\n          <i class=\"material-icons\">bar_chart</i> Quarter Filter\r\n        </button>\r\n        <button class=\"psr-mode-btn\" [class.active]=\"mode === 'lifetime'\" (click)=\"switchMode('lifetime')\">\r\n          <i class=\"material-icons\">person_search</i> Individual / Lifetime\r\n        </button>\r\n      </div>\r\n\r\n      <!-- ── QUARTER MODE filter ── -->\r\n      <div class=\"psr-filter-card\" *ngIf=\"mode === 'quarter'\">\r\n        <div class=\"psr-filter-row\">\r\n\r\n          <mat-form-field class=\"cs-input psr-field\">\r\n            <mat-label>Quarter</mat-label>\r\n            <mat-select [(ngModel)]=\"filter.quarter\">\r\n              <mat-option *ngFor=\"let q of quarters\" [value]=\"q\">{{q}}</mat-option>\r\n            </mat-select>\r\n          </mat-form-field>\r\n\r\n          <mat-form-field class=\"cs-input psr-field\">\r\n            <mat-label>Year</mat-label>\r\n            <mat-select [(ngModel)]=\"filter.year\">\r\n              <mat-option *ngFor=\"let y of years\" [value]=\"y\">{{y}}</mat-option>\r\n            </mat-select>\r\n          </mat-form-field>\r\n\r\n          <mat-form-field class=\"cs-input psr-field\">\r\n            <mat-label>Achievement % (below)</mat-label>\r\n            <input matInput type=\"number\" min=\"0\" max=\"100\" [(ngModel)]=\"filter.percentage\" placeholder=\"e.g. 80\">\r\n          </mat-form-field>\r\n\r\n          <button mat-raised-button color=\"primary\" class=\"psr-search-btn\" (click)=\"getList()\" [disabled]=\"loader\">\r\n            <i class=\"material-icons\">search</i> Search\r\n          </button>\r\n\r\n        </div>\r\n        <div class=\"psr-hint\">\r\n          <i class=\"material-icons\">info</i>\r\n          Shows employees whose secondary achievement in the selected quarter is below the entered %.\r\n        </div>\r\n      </div>\r\n\r\n      <!-- ── LIFETIME MODE filter ── -->\r\n      <div class=\"psr-filter-card\" *ngIf=\"mode === 'lifetime'\">\r\n        <div class=\"psr-lifetime-row\">\r\n\r\n          <div class=\"psr-autocomplete-wrap\">\r\n            <mat-form-field class=\"cs-input psr-field-lg\">\r\n              <mat-label>Search Employee</mat-label>\r\n              <input matInput\r\n                     [(ngModel)]=\"userSearchText\"\r\n                     (input)=\"getReportManager(userSearchText)\"\r\n                     (blur)=\"report_manager=[]\"\r\n                     placeholder=\"Type name to search...\">\r\n              <button mat-icon-button matSuffix *ngIf=\"selectedUser\" (click)=\"clearUser()\">\r\n                <i class=\"material-icons\" style=\"font-size:16px;\">close</i>\r\n              </button>\r\n            </mat-form-field>\r\n\r\n            <div class=\"psr-dropdown\" *ngIf=\"report_manager.length > 0\">\r\n              <div class=\"psr-dropdown-item\"\r\n                   *ngFor=\"let u of report_manager\"\r\n                   (mousedown)=\"selectUser(u)\">\r\n                <span class=\"pd-name\">{{u.name}}</span>\r\n                <span class=\"pd-meta\">{{u.employee_id}} &bull; {{u.designation_name}}</span>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <button mat-raised-button color=\"primary\" class=\"psr-search-btn\"\r\n                  (click)=\"generateLifetimeReport()\"\r\n                  [disabled]=\"lifetimeLoader || !selectedUser\">\r\n            <mat-spinner diameter=\"16\" *ngIf=\"lifetimeLoader\" style=\"display:inline-block;margin-right:6px;\"></mat-spinner>\r\n            <i class=\"material-icons\" *ngIf=\"!lifetimeLoader\">visibility</i>\r\n            Generate Preview\r\n          </button>\r\n\r\n        </div>\r\n        <div class=\"psr-hint\" *ngIf=\"selectedUser\">\r\n          <i class=\"material-icons\">check_circle</i>\r\n          <strong>{{selectedUser.name}}</strong> &nbsp;({{selectedUser.employee_id}}) — Preview opens below; edit any value, then download.\r\n        </div>\r\n        <div class=\"psr-hint\" *ngIf=\"!selectedUser\">\r\n          <i class=\"material-icons\">info</i>\r\n          Search and select an employee to preview their performance report before download.\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Quarter mode: Loader -->\r\n      <div class=\"psr-center\" *ngIf=\"loader\">\r\n        <mat-spinner diameter=\"40\"></mat-spinner>\r\n        <p>Fetching employees...</p>\r\n      </div>\r\n\r\n      <!-- Quarter mode: No data -->\r\n      <div class=\"psr-center psr-empty\" *ngIf=\"!loader && datanotfound && mode === 'quarter'\">\r\n        <i class=\"material-icons\">sentiment_satisfied_alt</i>\r\n        <p>No employees found below this threshold.</p>\r\n      </div>\r\n\r\n      <!-- Quarter mode: Employee Cards Grid -->\r\n      <div class=\"psr-cards-grid\" *ngIf=\"!loader && employees.length > 0 && mode === 'quarter'\">\r\n        <div class=\"psr-emp-card\" *ngFor=\"let emp of employees\"\r\n             (click)=\"downloadReport(emp)\"\r\n             [class.psr-card-downloading]=\"detailLoader\">\r\n\r\n          <div class=\"psr-avatar\">\r\n            <i class=\"material-icons\">account_circle</i>\r\n          </div>\r\n\r\n          <div class=\"psr-info\">\r\n            <div class=\"psr-name\">{{emp.name}}</div>\r\n            <div class=\"psr-meta\">{{emp.employee_id}} &bull; {{emp.designation}}</div>\r\n            <div class=\"psr-joining\" *ngIf=\"emp.joining_date && emp.joining_date !== '0000-00-00'\">\r\n              Joined: {{emp.joining_date | date:'dd MMM yyyy'}}\r\n            </div>\r\n            <div class=\"psr-ach\">\r\n              <span class=\"psr-ach-label\">Secondary Ach:</span>\r\n              <span class=\"psr-ach-val\"\r\n                    [ngClass]=\"emp.ach_pct >= 60 ? 'ach-ok' : emp.ach_pct >= 30 ? 'ach-warn' : 'ach-bad'\">\r\n                {{emp.ach_pct | number:'1.1-1'}}%\r\n              </span>\r\n              <span class=\"psr-ach-detail\">({{emp.sec_ach}} / {{emp.sec_target}})</span>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"psr-action\">\r\n            <i class=\"material-icons\" *ngIf=\"!detailLoader\">visibility</i>\r\n            <mat-spinner diameter=\"18\" *ngIf=\"detailLoader\"></mat-spinner>\r\n            <span>Preview</span>\r\n          </div>\r\n\r\n        </div>\r\n      </div>\r\n\r\n      <!-- ── EDITABLE PREVIEW PANEL ── -->\r\n      <div class=\"psr-preview\" *ngIf=\"showPreview\">\r\n        <div class=\"psr-preview-toolbar\">\r\n          <span class=\"ppt-dot\"></span>\r\n          <span class=\"ppt-label\">Editable Preview</span>\r\n          <span class=\"ppt-hint\">— click any value to correct it, then download</span>\r\n          <span class=\"ppt-spacer\"></span>\r\n          <button mat-stroked-button class=\"ppt-btn\" (click)=\"closePreview()\">\r\n            <i class=\"material-icons\">close</i> Close\r\n          </button>\r\n          <button mat-stroked-button class=\"ppt-btn ppt-hl-btn\" [class.active]=\"highlightMode\"\r\n                  (click)=\"toggleHighlightMode()\">\r\n            <i class=\"material-icons\">border_color</i> {{ highlightMode ? 'Highlighter: ON' : 'Highlighter' }}\r\n          </button>\r\n          <button mat-stroked-button class=\"ppt-btn\" (click)=\"downloadExcel()\" [disabled]=\"excelLoader\">\r\n            <mat-spinner diameter=\"16\" *ngIf=\"excelLoader\" style=\"display:inline-block;margin-right:6px;\"></mat-spinner>\r\n            <i class=\"material-icons\" *ngIf=\"!excelLoader\">grid_on</i> Excel (all employees)\r\n          </button>\r\n          <button mat-raised-button color=\"primary\" class=\"ppt-btn\" (click)=\"downloadDoc()\">\r\n            <i class=\"material-icons\">file_download</i> Download .doc\r\n          </button>\r\n        </div>\r\n        <div class=\"psr-preview-body\"\r\n             #previewBody\r\n             [class.hl-mode]=\"highlightMode\"\r\n             contenteditable=\"true\"\r\n             (click)=\"onPreviewClick($event)\"\r\n             [innerHTML]=\"previewHtml\"></div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n\r\n</div>\r\n"

