module.exports = "<div class=\"main-container\">\r\n\r\n  <div class=\"tools-container\">\r\n    <h2>WhatsApp Group Report</h2>\r\n  </div>\r\n\r\n  <div class=\"wgr-page\">\r\n\r\n    <!-- Filter Card -->\r\n    <div class=\"wgr-filter-card\">\r\n      <div class=\"wgr-filter-header\">\r\n        <div class=\"wgr-filter-title\">\r\n          <i class=\"material-icons\">groups</i>\r\n          <div>\r\n            <h3>Generate WhatsApp Group Visit Report</h3>\r\n            <p>Daily visit data with Group Visit and Special Remark — ready to share on WhatsApp</p>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"wgr-filter-body\">\r\n        <div class=\"wgr-filter-row\">\r\n\r\n          <!-- Employee -->\r\n          <div class=\"wgr-field\">\r\n            <label class=\"wgr-label\"><i class=\"material-icons\">person</i> Employee</label>\r\n            <mat-form-field appearance=\"outline\" class=\"cs-input select-input wgr-select\">\r\n              <mat-select [(ngModel)]=\"filter.userId\" name=\"userId\" placeholder=\"Search employee...\">\r\n                <mat-option>\r\n                  <ngx-mat-select-search\r\n                    noEntriesFoundLabel=\"No employee found\"\r\n                    placeholderLabel=\"Search employee...\"\r\n                    (keyup)=\"getReportManager($event.target.value)\">\r\n                  </ngx-mat-select-search>\r\n                </mat-option>\r\n                <mat-option *ngFor=\"let u of report_manager\" [value]=\"u.id\">\r\n                  {{u.name}} — {{u.employee_id}} — {{u.role_name}}\r\n                </mat-option>\r\n              </mat-select>\r\n            </mat-form-field>\r\n          </div>\r\n\r\n          <!-- Month -->\r\n          <div class=\"wgr-field wgr-field--sm\">\r\n            <label class=\"wgr-label\"><i class=\"material-icons\">calendar_month</i> Month</label>\r\n            <mat-form-field appearance=\"outline\" class=\"cs-input select-input wgr-select\">\r\n              <mat-select [(ngModel)]=\"filter.month\" name=\"month\">\r\n                <mat-option *ngFor=\"let m of monthList\" [value]=\"m.id\">{{m.name}}</mat-option>\r\n              </mat-select>\r\n            </mat-form-field>\r\n          </div>\r\n\r\n          <!-- Year -->\r\n          <div class=\"wgr-field wgr-field--xs\">\r\n            <label class=\"wgr-label\"><i class=\"material-icons\">event</i> Year</label>\r\n            <mat-form-field appearance=\"outline\" class=\"cs-input select-input wgr-select\">\r\n              <mat-select [(ngModel)]=\"filter.year\" name=\"year\">\r\n                <mat-option *ngFor=\"let y of yearList\" [value]=\"y\">{{y}}</mat-option>\r\n              </mat-select>\r\n            </mat-form-field>\r\n          </div>\r\n\r\n          <!-- Download Button -->\r\n          <div class=\"wgr-field wgr-field--btn\">\r\n            <label class=\"wgr-label\">&nbsp;</label>\r\n            <button class=\"btn-wgr-download\" (click)=\"downloadReport()\" [disabled]=\"downloading || !isValid\">\r\n              <i class=\"material-icons\">{{downloading ? 'hourglass_top' : 'download'}}</i>\r\n              {{downloading ? 'Generating...' : 'Download Report'}}\r\n            </button>\r\n          </div>\r\n\r\n        </div>\r\n\r\n        <p class=\"wgr-hint\" *ngIf=\"!isValid\">\r\n          <i class=\"material-icons\">info</i>\r\n          Select employee, month and year to enable download\r\n        </p>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Info Card -->\r\n    <div class=\"wgr-info-card\" *ngIf=\"!downloading\">\r\n      <div class=\"wgr-info-head\">\r\n        <i class=\"material-icons\" style=\"color:#2E7D32\">table_view</i>\r\n        <span>What's included in this report</span>\r\n      </div>\r\n      <div class=\"wgr-cols-grid\">\r\n        <div class=\"wgr-col-chip\" *ngFor=\"let col of ['Date','Day','Plant Visit','Actual Visit','Unplan Visit','No Meeting','Visit > Once','Plan Follow%','Total Visit','Group Visit','Special Remark']\">\r\n          <i class=\"material-icons\">check_circle</i>\r\n          {{col}}\r\n        </div>\r\n      </div>\r\n      <p class=\"wgr-info-note\">\r\n        <i class=\"material-icons\">info</i>\r\n        Average is calculated as <strong>(Total Visit + Group Visit) / Working Days</strong> — excludes Weekly Off, Leave, Holiday and Absent days.\r\n      </p>\r\n    </div>\r\n\r\n    <!-- Generating -->\r\n    <div class=\"wgr-progress-card\" *ngIf=\"downloading\">\r\n      <div class=\"progress-icon\">\r\n        <i class=\"material-icons spin\">sync</i>\r\n      </div>\r\n      <div class=\"progress-content\">\r\n        <h3>Building your report...</h3>\r\n        <p>Fetching daily visit data. Please wait.</p>\r\n        <div class=\"progress-bar-wrap\">\r\n          <div class=\"progress-bar-fill\"></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</div>\r\n"

